const items = $input.all();
const body = items[0]?.json?.body;
const entry = body?.entry?.[0]?.messaging?.[0];
const text = entry?.message?.text;
const senderId = entry?.sender?.id;

// Check for both regular postbacks AND quick replies
const postback = entry?.postback?.payload || entry?.message?.quick_reply?.payload;

const staticData = $getWorkflowStaticData('global');
const senderKey = `user_${senderId}`;

const previous = staticData[senderKey]?.previousPostback || null;
const latest = staticData[senderKey]?.latestPostback || null;

function isSizeSelected(payload) {
  if (!payload) return false;
  const parts = payload.split('|');
  return parts.length === 2 && parts[0].length > 0 && parts[1].length > 0;
}

function isAddOnSelected(payload) {
  if (!payload) return false;
  const parts = payload.split('|');
  return parts.length === 3 && parts.every(part => part.length > 0);
}

const sizeSelected = isSizeSelected(postback);
const isAddOnSelectedFlag = isAddOnSelected(postback);

if (
  body?.object === 'page' &&
  senderId
) {
  if (text && !postback && text.trim().toLowerCase() === 'get started') {
    return [{
      json: {
        type: 'text',
        text: 'get started',
        senderId,
        previousPostback: previous,
        latestPostback: latest,
        sizeSelected: false,
        isAddOnSelected: false
      }
    }];
  }
  if (postback) {
    staticData[senderKey] = {
      previousPostback: latest,
      latestPostback: postback,
      sizeSelected,
      isAddOnSelected: isAddOnSelectedFlag
    };
    return [{
      json: {
        type: 'postback',
        postback,
        senderId,
        previousPostback: previous,
        latestPostback: postback,
        sizeSelected,
        isAddOnSelected: isAddOnSelectedFlag
      }
    }];
  }
  return [];
} else {
  return [{
    json: { error: 'Invalid payload or missing sender' }
  }];
}

